if (number(1, 100) <= iSecondPct)

// MT2009_PLUS_DROP_BONUS_PCT_V1 (pending) (server-patches/dropbonus): SetDropRarePct, which every
// monster drop asks just before its CreateItem, leaves the panels' percent of
// the bonus chance here (m2_drop_bonus_pct; 0 = the game's own chance) and
