new:
int real_chance = iRarePct > 0 ? (iRarePct + addRarePct) : 0;

// MT2009_PLUS_DROP_BONUS_PCT_V1 (chance): a monster's drop at the panels' percent of
// the game's chance. An ordinary monster's weapon or armour, which
// the game never gives a bonus, gets the item's own chance times the
// excess above 100% (200% = what its table says).
if (dropBonusPct > 0)
{
	if (real_chance > 0)
		real_chance = real_chance * dropBonusPct / 100;
	else if (dropBonusPct > 100 && base_rare_pct > 0)
		real_chance = base_rare_pct * (dropBonusPct - 100) / 100 + addRarePct;
}

if (number(1, 100) <= real_chance)
{
	g_iMt2009PlusDropBonusPct = dropBonusPct;
	item->AlterToMagicItem();
	g_iMt2009PlusDropBonusPct = 0;
}

void SetDropRarePct(LPCHARACTER pkMob, int& rarePct, TItemTable * itemTable)
{
	// MT2009_PLUS_DROP_BONUS_PCT_V1 (flag): the panels' percent for the CreateItem that follows
	// (10..1000; 0, 100 or no flag = the game's own chance).
	s_iMt2009PlusDropBonusPending = 0;
	if (pkMob && itemTable)
	{
		const int pct = quest::CQuestManager::instance().GetEventFlag("m2_drop_bonus_pct");
		if (pct > 0 && pct != 100)
			s_iMt2009PlusDropBonusPending = MINMAX(10, pct, 1000);
	}
